    }
    const store = {
      subscribe(fn) { listeners.add(fn); if (!started) { started = true; refresh(false, true).then(schedule, schedule); } return () => { listeners.delete(fn); if (listeners.size === 0) { started = false; if (timer !== null) { clearTimeout(timer); timer = null; } } }; },
      getSnapshot() { return snapshot; },
      forceRefresh() { return refresh(true); },
    };
    //#endregion

    //#region helpers
    const CURRENCY_SYMBOLS = { CNY: "¥", USD: "$", EUR: "€" };
    const currencySymbol = (c) => { if (c === "%" || c === "tokens") return ""; return CURRENCY_SYMBOLS[c] || c + " "; };
    /**
     * v1.3.2: 会话消耗格式化 —— 海外模型可独立走 USD, 一个会话可能同时有两种货币。
     * 不做汇率折算合并 (折算=再引入 ×7 误差, 正是用户「¥1285 被看成 $1285」的成因),
     * 改为两段拼接: ~¥3.40+$12.50。主货币排在前。
     * 返回 { text, title, mixed }; 无数据返回 null。
     */
    function formatSessionCost(cost) {
      if (!cost || typeof cost.cost !== "number" || cost.waiting === true) return null;
      const mainCur = cost.currency || "CNY";
      const symOf = (c) => (c === "CNY" ? "¥" : c === "USD" ? "$" : c + " ");
      const fixOf = (a) => (a >= 1 ? 2 : a >= 0.01 ? 3 : a >= 0.001 ? 4 : a >= 0.0001 ? 5 : 6);
      const byCur = cost.costByCurrency && typeof cost.costByCurrency === "object" ? cost.costByCurrency : null;
      let segs = [];
      if (byCur) {
        segs = Object.keys(byCur)
          .filter((k) => typeof byCur[k] === "number" && byCur[k] > 0)
          .sort((a, b) => (a === mainCur ? -1 : b === mainCur ? 1 : byCur[b] - byCur[a]))
          .map((k) => ({ cur: k, amount: byCur[k] }));
      }
      // 旧 bundle / 未开启独立币种 / 全零 → 退回单段, 行为同 v1.2.6
      if (segs.length === 0) segs = [{ cur: mainCur, amount: cost.cost }];
      const mixed = segs.length > 1;
      // hasValue: 是否真有非零金额。不能用 cost.cost > 0 判断 —— 开启海外独立币种后,
      // 纯 claude 会话的主货币段就是 0, 金额全在 USD 段里 (详情页会误显示成「—」)。
      const hasValue = segs.some((x) => x.amount > 0);
      return {
        text: segs.map((x) => symOf(x.cur) + x.amount.toFixed(fixOf(x.amount))).join("+"),
        title: segs.map((x) => symOf(x.cur) + x.amount.toFixed(6)).join(" + ") + (mixed ? " (两种货币, 未按汇率合并)" : ""),
        mixed: mixed,
        hasValue: hasValue,
      };
    }
    /* ===== v1.4.0 子代理胶囊 · 长按详情浮层 =====
     * 为什么不用 title: **手机上 title 根本不显示**, 长按弹的是系统「选择/复制」菜单
     * (用户实测反馈「长按只能复制」)。所以自己用 pointerdown 计时器弹浮层, 并靠 CSS 的
     * user-select:none + -webkit-touch-callout:none 把系统菜单压掉。
     * 浮层必须挂 document.body —— 挂在胶囊里会被 .dshadb_subs 的 overflow-x:auto 裁掉。
     */
    // 单击详情，不再依赖触屏长按。
    let subTipNode = null;
    let subTipTimer = 0;
    let subTipDismissBound = false;
    function hideSubagentTip() {
      if (subTipTimer) { clearTimeout(subTipTimer); subTipTimer = 0; }
      if (subTipNode && subTipNode.parentNode) subTipNode.parentNode.removeChild(subTipNode);
      subTipNode = null;
    }
    /** 浮层摆在胶囊上方; 上方放不下翻到下方; 左右夹在视口内。 */
    function showSubagentTip(anchor, text) {
      hideSubagentTip();
      if (!anchor || !text) return;
      const el = document.createElement("div");
      el.className = "dshadb_subtip";
      el.setAttribute("role", "dialog");
      el.setAttribute("aria-label", "子代理详情");
      const lines = String(text).split("\n");
      const title = document.createElement("strong"); title.textContent = lines.shift(); el.appendChild(title);
      lines.forEach(line => {
        const row = document.createElement("div"); row.className = "dshadb_subtip_row";
        const split = line.indexOf(" ");
        const label = document.createElement("span"); label.textContent = split >= 0 ? line.slice(0, split) : "";
        const value = document.createElement("b"); value.textContent = split >= 0 ? line.slice(split + 1) : line;
        row.appendChild(label); row.appendChild(value); el.appendChild(row);
      });
      const close = document.createElement("button"); close.type = "button"; close.textContent = "关闭"; close.onclick = hideSubagentTip; el.appendChild(close);
      el.addEventListener("pointerdown", e => e.stopPropagation());
      el.tabIndex = -1;
      document.body.appendChild(el);
      subTipNode = el;
      const rect = anchor.getBoundingClientRect ? anchor.getBoundingClientRect() : null;
      const vw = window.innerWidth || 360;
      const vh = window.innerHeight || 640;
      const w = el.offsetWidth || Math.min(240, vw - 24);
      const h = el.offsetHeight || 60;
      let top = rect ? rect.top - h - 8 : 16;
      if (top < 8) top = rect ? Math.min(vh - h - 8, rect.bottom + 8) : 8;
      const left = rect ? rect.left : 12;
      el.style.left = Math.max(8, Math.min(vw - w - 8, left)) + "px";
      el.style.top = Math.max(8, top) + "px";
      // 单击详情保持可读，点外部或关闭按钮收起。
    }
    function bindSubTipDismiss() {
      if (subTipDismissBound) return;
      subTipDismissBound = true;
      // 点别处 / 滚动 / 转屏都收起。capture 阶段先于胶囊自己的 pointerdown 跑,
      // 所以「已开着一个浮层时再长按另一个胶囊」不会被立刻收掉。
      document.addEventListener("pointerdown", (e) => { if (!subTipNode?.contains(e.target)) hideSubagentTip(); }, true);
      window.addEventListener("scroll", hideSubagentTip, true);
      window.addEventListener("resize", hideSubagentTip);
      document.addEventListener("keydown", e => { if (e.key === "Escape") hideSubagentTip(); });
    }
    /** 给一个胶囊挂长按: 位移 > 8px(其实是在滑动这一行) 或抬手都取消; 长按抬手后的 click 吞掉。 */
    function bindSubagentTip(node, text) {
      node.__dshadbTip = text;
      if (node.__dshadbTipBound === true) return;
      node.__dshadbTipBound = true;
      node.addEventListener("click", (e) => {
        e.preventDefault(); e.stopPropagation(); bindSubTipDismiss();
        showSubagentTip(node, node.__dshadbTip || text);
      });
      node.addEventListener("contextmenu", e => e.preventDefault());
    }
    /**
