      // - tokens: 数量>0 安全, <=0 异常 (token 数是规模非金额)
      const cur = String(b.currency || "").trim();
      if (cur === "tokens") {
        const v = typeof b.total === "number" ? b.total : (b.available ?? 0);
        if (!Number.isFinite(v)) return "err";
        return v > 0 ? "ok" : "err";
